            @RequestParam(name = "order", required = false, defaultValue = "desc") String order) {
        return ApiResponse.success("查询成功", banEventService.findAll(sortBy, order));
    }

    @GetMapping("/{id}")
    public ApiResponse<BanEvent> detail(@PathVariable("id") Long id) {
        BanEvent event = banEventService.findById(id);
        if (event == null) {
            return ApiResponse.error(404, "事件不存在");
        }
        return ApiResponse.success("查询成功", event);
    }
}

